CustomField.formula:
/*First if completed same day*/
if( DateValue(Latest_Sent_to_Closed_Tracking_Only__c)=DateValue(Latest_Closed_Returned_Formula__c),
/*Adjusts Closed Hour/Minute if it's before or after hours*/
if(Latest_Closed_Returned_Formula_Hour__c<8, 8, if(Latest_Closed_Returned_Formula_Hour__c>20, 20, Latest_Closed_Returned_Formula_Hour__c))+
if(Latest_Closed_Returned_Formula_Hour__c<8 || Latest_Closed_Returned_Formula_Hour__c>20, 0, Minute(TimeValue(NOW()))/60)
-
(if(if(Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))<=5, 24, 0) + Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))-5<8, 8, if(if(Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))<=5, 24, 0) + Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))-5>20, 20, if(Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))<=5, 24, 0) + Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))-5))+
if(if(Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))<=5, 24, 0) + Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))-5<8 || if(Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))<=5, 24, 0) + Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))-5>20 ,0, Minute(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c)))/60),

if( Weekday(DateValue(Latest_Sent_to_Closed_Tracking_Only__c))=7 || Weekday(DateValue(Latest_Sent_to_Closed_Tracking_Only__c))=0 || if(Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))<=5, 24, 0) + Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))-5>=20, 0,
if(if(Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))<=5, 24, 0) + Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))-5<8, 8, 20-(if(Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))<=5, 24, 0) + Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))-5))+
if(if(Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))<=5, 24, 0) + Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))-5<8 || if(Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))<=5, 24, 0) + Hour(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))-5>20, 0, (Minute(TimeValue(Latest_Sent_to_Closed_Tracking_Only__c))/60))
)+
(CASE( WEEKDAY(DateValue(Latest_Sent_to_Closed_Tracking_Only__c)),
/*This excludes End Dates e.g. Mon Tuesday Wednesday = 1*/
1 , CASE( MOD( DateValue(Latest_Closed_Returned_Formula__c)-DateValue(Latest_Sent_to_Closed_Tracking_Only__c),7),1,0,2,1,3,2,4,3,5,4,6,5,0),
2 , CASE( MOD( DateValue(Latest_Closed_Returned_Formula__c)-DateValue(Latest_Sent_to_Closed_Tracking_Only__c),7),1,0,2,1,3,2,4,3,5,3,6,3,0),
3 , CASE( MOD( DateValue(Latest_Closed_Returned_Formula__c)-DateValue(Latest_Sent_to_Closed_Tracking_Only__c),7),1,0,2,1,3,2,4,2,5,2,6,3,0),
4 , CASE( MOD( DateValue(Latest_Closed_Returned_Formula__c)-DateValue(Latest_Sent_to_Closed_Tracking_Only__c),7),1,0,2,1,3,1,4,1,5,2,6,3,0),
5 , CASE( MOD( DateValue(Latest_Closed_Returned_Formula__c)-DateValue(Latest_Sent_to_Closed_Tracking_Only__c),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
6 , CASE( MOD( DateValue(Latest_Closed_Returned_Formula__c)-DateValue(Latest_Sent_to_Closed_Tracking_Only__c),7),1,0,2,0,3,0,4,1,5,2,6,3,0),
7 , CASE( MOD( DateValue(Latest_Closed_Returned_Formula__c)-DateValue(Latest_Sent_to_Closed_Tracking_Only__c),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
999)
+
(FLOOR(( DateValue(Latest_Closed_Returned_Formula__c)-DateValue(Latest_Sent_to_Closed_Tracking_Only__c) )/7)*5))*8
+
if(Latest_Closed_Returned_Formula_Hour__c<8, 0, if(Latest_Closed_Returned_Formula_Hour__c>20, 20, Latest_Closed_Returned_Formula_Hour__c-8))+
if(Latest_Closed_Returned_Formula_Hour__c<8 || Latest_Closed_Returned_Formula_Hour__c>20, 0, (Minute(TimeValue(NOW()))/60))
)
